/* =========================================================================
 * BubbleSprites — official production bubble artwork (from Elements.rar).
 *
 * The six PNGs are the single source of truth for bubble visuals. They are
 * inlined as data URIs so the game remains ONE self-contained HTML file with
 * no external asset loading (the web equivalent of a packed sprite atlas: each
 * colour is a single shared Image, reused for every bubble — no duplication).
 *
 * CENTRALISED colour -> sprite mapping (edit here only; never hardcode sprite
 * references elsewhere). Gameplay colour keys map to asset keys via ALIAS, so
 * the existing 5-colour gameplay ('yellow') renders the gold artwork.
 *
 *   ballRed.png    -> red      ballBlue.png   -> blue
 *   ballGreen.png  -> green    ballGold.png   -> gold  (gameplay 'yellow')
 *   ballOrange.png -> orange   ballPurple.png -> purple
 * ========================================================================= */
const BubbleSprites = (() => {
  const DATA = {
    red: 'data:image/png;base64,',
    blue: 'data:image/png;base64,',
    green: 'data:image/png;base64,',
    gold: 'data:image/png;base64,',
    orange: 'data:image/png;base64,',
    purple: 'data:image/png;base64,',
  };

  // gameplay colour -> asset key (visual-only alias; gameplay logic unchanged)
  const ALIAS = { yellow: 'gold' };
  const images = {};
  let ready = false;

  const keyFor = (color) => ALIAS[color] || color;

  // Preload every sprite. Resolves when all are decoded (or immediately in a
  // headless/Node environment where Image is unavailable).
  function load() {
    if (typeof Image === 'undefined') { ready = true; return Promise.resolve(); }
    const keys = Object.keys(DATA);
    return Promise.all(keys.map((k) => new Promise((res) => {
      const img = new Image();
      img.onload = () => res();
      img.onerror = () => res();
      img.src = DATA[k];
      images[k] = img;
    }))).then(() => { ready = true; });
  }

  // Return the decoded Image for a gameplay colour, or null if not ready.
  function image(color) {
    const img = images[keyFor(color)];
    return (img && img.complete && img.naturalWidth > 0) ? img : null;
  }

  return { DATA, ALIAS, load, image, keyFor, isReady: () => ready };
})();
